const input = $input.first().json;
const body = input.body || input;
const data = body.data || {};
const key = data.key || {};
const message = data.message || {};
const instanceName = body.instance || body.instanceName || body.instance_name || input.instanceName;
const remoteJid = key.remoteJid || data.remoteJid || data.sender || '';
const messageType = data.messageType || data.message_type || (message.audioMessage ? 'audioMessage' : 'conversation');
const fromMe = key.fromMe === true;
const event = body.event || '';
const validEvent = !event || event === 'messages.upsert' || event === 'MESSAGES_UPSERT';
if (!validEvent || fromMe || !instanceName || !remoteJid || remoteJid.includes('@g.us') || remoteJid === 'status@broadcast') return [];
const userMessage = message.conversation || message.extendedTextMessage?.text || data.message?.conversation || data.text || '';
const customerPhone = String(remoteJid).split('@')[0].replace(/\D/g, '');
return [{ json: { ...input, body, event, instanceName, remoteJid, customerPhone, customerName: data.pushName || data.pushname || body.senderName || null, messageId: key.id || data.id || null, messageType, userMessage, hasAudio: messageType === 'audioMessage', rawMessage: message, receivedAt: new Date().toISOString() } }];

const original = $('Normalize Incoming Message').first().json;
const payload = $input.first().json;
const base64 = payload.base64 || payload.data || payload.file || payload.media || '';
const mimeType = payload.mimetype || payload.mimeType || 'audio/ogg';
if (!base64) return [{ json: { ...original, userMessage: '', audioError: 'Audio sem base64 retornado pela Evolution API' } }];
return [{ json: { ...original }, binary: { data: { data: base64, mimeType, fileName: 'audio.ogg' } } }];

const original = $('Normalize Incoming Message').first().json;
const transcript = $input.first().json.text || $input.first().json.transcription || '';
return [{ json: { ...original, userMessage: transcript, transcription: transcript, messageType: 'audioMessage' } }];

const item = $input.first().json;
const required = ['evolutionApiUrl', 'evolutionApiKey', 'supabaseUrl', 'supabaseServiceRoleKey'];
for (const key of required) if (!item[key]) throw new Error(`Variavel obrigatoria ausente: ${key}`);
const sb = item.supabaseUrl.replace(/\/+$/, '');
const headers = { apikey: item.supabaseServiceRoleKey, Authorization: `Bearer ${item.supabaseServiceRoleKey}`, 'Content-Type': 'application/json' };
async function rest(path, options = {}) {
  const res = await fetch(`${sb}/rest/v1/${path}`, { ...options, headers: { ...headers, ...(options.headers || {}) } });
  const text = await res.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  if (!res.ok) throw new Error(`Supabase ${res.status} ${path}: ${text}`);
  return json;
}
function enc(v) { return encodeURIComponent(String(v)); }
function fallbackFrom(settings) {
  try { const extra = JSON.parse(settings?.additional_instructions || '{}'); return extra.fallback_message || 'Vou transferir você para um atendente humano.'; } catch { return 'Vou transferir você para um atendente humano.'; }
}
function isInsideBusinessHours(settings) {
  if (!settings?.business_hours_only || !settings.business_hours) return true;
  const now = new Date();
  const dayKey = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'][now.getDay()];
  const day = settings.business_hours[dayKey];
  if (!day?.enabled) return false;
  const hhmm = now.toISOString().slice(11, 16);
  return hhmm >= day.start && hhmm <= day.end;
}
const instances = await rest(`whatsapp_instances?instance_name=eq.${enc(item.instanceName)}&is_active=eq.true&select=id,restaurant_id,instance_name,status,automation_enabled,is_active&limit=1`);
const instance = Array.isArray(instances) ? instances[0] : instances;
if (!instance?.id) return [];
const restaurantId = instance.restaurant_id;
const [settingsRows, restaurantRows, rules, products, recentOrders, threadRows] = await Promise.all([
  rest(`automation_settings?instance_id=eq.${enc(instance.id)}&select=*&limit=1`),
  rest(`restaurants?id=eq.${enc(restaurantId)}&select=id,name,slug,phone,phone_whatsapp,business_hours,category&limit=1`),
  rest(`ai_handoff_rules?instance_id=eq.${enc(instance.id)}&is_active=eq.true&select=rule_type,rule_value,priority&order=priority.asc`),
  rest(`products?restaurant_id=eq.${enc(restaurantId)}&available=eq.true&select=id,name,description,price,category_id&order=order_position.asc&limit=100`),
  rest(`delivery_orders?restaurant_id=eq.${enc(restaurantId)}&customer_phone=ilike.*${enc(item.customerPhone.slice(-8))}*&select=id,status,total,created_at,estimated_delivery_minutes&order=created_at.desc&limit=3`),
  rest(`conversation_threads?restaurant_id=eq.${enc(restaurantId)}&instance_id=eq.${enc(instance.id)}&remote_jid=eq.${enc(item.remoteJid)}&select=*&limit=1`)
]);
const settings = (Array.isArray(settingsRows) ? settingsRows[0] : settingsRows) || { ai_enabled: true, bot_name: 'Atendente Virtual', ai_persona: 'Atendente simpatico e profissional', use_menu_knowledge: true, auto_handoff_enabled: true, auto_handoff_confidence_threshold: 0.3, welcome_message: 'Olá! Como posso ajudar?' };
const restaurant = (Array.isArray(restaurantRows) ? restaurantRows[0] : restaurantRows) || { id: restaurantId, name: 'Loja' };
let thread = Array.isArray(threadRows) ? threadRows[0] : threadRows;
const preview = (item.userMessage || '[audio]').slice(0, 120);
if (!thread?.id) {
  const created = await rest('conversation_threads', { method: 'POST', headers: { Prefer: 'return=representation' }, body: JSON.stringify({ restaurant_id: restaurantId, instance_id: instance.id, remote_jid: item.remoteJid, customer_phone: item.customerPhone, customer_name: item.customerName, status: 'bot_active', unread_count: 1, last_message_at: item.receivedAt, last_message_preview: preview, metadata: { instanceName: item.instanceName } }) });
  thread = Array.isArray(created) ? created[0] : created;
} else {
  await rest(`conversation_threads?id=eq.${enc(thread.id)}`, { method: 'PATCH', body: JSON.stringify({ unread_count: Number(thread.unread_count || 0) + 1, last_message_at: item.receivedAt, last_message_preview: preview, customer_name: item.customerName || thread.customer_name }) });
}
await rest('conversation_messages', { method: 'POST', body: JSON.stringify({ thread_id: thread.id, restaurant_id: restaurantId, sender_type: 'customer', content: item.userMessage || '[Audio sem transcricao]', message_type: item.messageType || 'text', metadata: { messageId: item.messageId, remoteJid: item.remoteJid, transcription: item.transcription || null } }) });
const lower = String(item.userMessage || '').toLowerCase();
const keywordRules = (rules || []).filter(r => ['keyword', 'customer_request'].includes(r.rule_type) && r.rule_value);
const matchedRule = keywordRules.find(r => lower.includes(String(r.rule_value).toLowerCase()));
const outsideHours = !isInsideBusinessHours(settings);
const automationEnabled = instance.automation_enabled !== false && settings.ai_enabled !== false;
const needsHuman = Boolean(settings.auto_handoff_enabled && matchedRule) || outsideHours;
const fallbackMessage = outsideHours ? 'No momento estamos fora do horario de atendimento. Sua mensagem ficou registrada e retornaremos assim que possivel.' : fallbackFrom(settings);
if (needsHuman) {
  await rest(`conversation_threads?id=eq.${enc(thread.id)}`, { method: 'PATCH', body: JSON.stringify({ status: 'waiting_human' }) });
}
const shouldUseAI = automationEnabled && !needsHuman && thread.status !== 'human_active' && thread.status !== 'waiting_human' && thread.status !== 'closed' && Boolean(item.userMessage);
const menuSummary = settings.use_menu_knowledge === false ? 'Cardapio nao habilitado para IA.' : (products || []).map(p => `- ${p.name}: R$ ${Number(p.price || 0).toFixed(2)}${p.description ? ` | ${p.description}` : ''}`).join('\n');
const ordersSummary = (recentOrders || []).map(o => `- Pedido ${String(o.id).slice(0, 8)}: ${o.status}, total R$ ${Number(o.total || 0).toFixed(2)}, criado em ${o.created_at}`).join('\n') || 'Nenhum pedido recente encontrado para este telefone.';
const handoffSummary = keywordRules.map(r => r.rule_value).filter(Boolean).join(', ') || 'sem palavras-chave configuradas';
const systemPrompt = `Voce e ${settings.bot_name || 'Atendente Virtual'}, atendente virtual de ${restaurant.name}.\nResponda em portugues brasileiro, de forma objetiva e cordial.\nPersona/tom: ${settings.ai_persona || 'profissional e simpatico'}.\n\nRegras obrigatorias:\n- Atenda somente esta loja e esta instancia: ${item.instanceName}.\n- Use apenas o cardapio e contexto recebidos. Nao invente produto, preco, prazo, status ou politica.\n- Se o cliente quiser montar pedido, colete itens, quantidades, observacoes, entrega/retirada, endereco e pagamento.\n- Para pedidos ja feitos pelo menu delivery, use o contexto de pedidos recentes.\n- Se o cliente pedir humano, reclamar, cancelar, falar de problema de pagamento, ou a confianca for baixa, devolva action=handoff.\n- Palavras de handoff: ${handoffSummary}.\n\nCardapio disponivel:\n${menuSummary || 'Sem produtos disponiveis.'}\n\nPedidos recentes deste cliente:\n${ordersSummary}\n\nResponda sempre em JSON valido neste formato:\n{"action":"reply|handoff|order_status|create_order_draft","message":"texto para enviar ao cliente","confidence":0.0,"handoff_reason":null,"order_draft":null}`;
return [{ json: { ...item, instance, restaurant, automation: settings, handoffRules: rules || [], products: products || [], recentOrders: recentOrders || [], thread, threadId: thread.id, shouldUseAI, action: needsHuman ? 'handoff' : 'reply', outboundText: needsHuman ? fallbackMessage : '', handoffReason: matchedRule?.rule_value || (outsideHours ? 'outside_business_hours' : null), systemPrompt, aiInput: item.userMessage } }];

const base = $('Load Context and Persist Incoming').first().json;
const raw = $input.first().json.output || $input.first().json.text || '';
let parsed;
try { parsed = JSON.parse(String(raw).replace(/^```json\s*/i, '').replace(/```$/i, '').trim()); } catch { parsed = { action: 'reply', message: String(raw), confidence: 0.7, handoff_reason: null, order_draft: null }; }
const outboundText = parsed.message || 'Desculpe, nao consegui gerar uma resposta agora. Vou encaminhar para um atendente.';
return [{ json: { ...base, aiRawOutput: raw, aiResult: parsed, action: parsed.action || 'reply', outboundText, confidence: Number(parsed.confidence ?? 0.7), handoffReason: parsed.handoff_reason || null } }];

const item = $input.first().json;
if (!item.outboundText) return [];
return [{ json: item }];

const item = $input.first().json;
if (!item.outboundText) return [];
return [{ json: { ...item, outboundText: String(item.outboundText).slice(0, 3500) } }];

const item = $('Prepare Outbound Message').first().json;
const sendResult = $input.first().json;
const sb = item.supabaseUrl.replace(/\/+$/, '');
const headers = { apikey: item.supabaseServiceRoleKey, Authorization: `Bearer ${item.supabaseServiceRoleKey}`, 'Content-Type': 'application/json' };
async function rest(path, options = {}) {
  const res = await fetch(`${sb}/rest/v1/${path}`, { ...options, headers: { ...headers, ...(options.headers || {}) } });
  const text = await res.text();
  if (!res.ok) throw new Error(`Supabase ${res.status} ${path}: ${text}`);
  try { return text ? JSON.parse(text) : null; } catch { return text; }
}
function enc(v) { return encodeURIComponent(String(v)); }
if (item.action === 'handoff') {
  await rest(`conversation_threads?id=eq.${enc(item.threadId)}`, { method: 'PATCH', body: JSON.stringify({ status: 'waiting_human' }) });
}
await rest('conversation_messages', { method: 'POST', body: JSON.stringify({ thread_id: item.threadId, restaurant_id: item.restaurant.id, sender_type: item.action === 'handoff' ? 'bot' : 'bot', content: item.outboundText, message_type: 'text', metadata: { action: item.action, confidence: item.confidence || null, handoffReason: item.handoffReason || null, evolution_result: sendResult } }) });
await rest(`conversation_threads?id=eq.${enc(item.threadId)}`, { method: 'PATCH', body: JSON.stringify({ last_message_at: new Date().toISOString(), last_message_preview: item.outboundText.slice(0, 120), unread_count: 0 }) });
return [{ json: { success: true, threadId: item.threadId, action: item.action, sentText: item.outboundText, evolution: sendResult } }];
